namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events, civilizations, and cultural development." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in distributed systems and cloud computing. She has published over 40 papers and previously worked at major tech companies.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Morton", Title = "Professor", Bio = "Dr. Morton is an expert in abstract algebra and number theory with 20 years of teaching experience.", Email = "j.morton@university.edu" },
            new() { Id = 3, Name = "Dr. Emily Park", Title = "Assistant Professor", Bio = "Dr. Park researches modern American literature and creative writing pedagogy.", Email = "e.park@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Singh", Title = "Professor", Bio = "Dr. Singh is a leading researcher in quantum mechanics and particle physics with multiple grants from national science foundations.", Email = "r.singh@university.edu" },
            new() { Id = 5, Name = "Dr. Maria González", Title = "Associate Professor", Bio = "Dr. González specializes in medieval European history and has authored three books on the subject.", Email = "m.gonzalez@university.edu" },
            new() { Id = 6, Name = "Dr. Alan Turing II", Title = "Senior Lecturer", Bio = "Dr. Turing focuses on artificial intelligence and machine learning, bringing industry experience to the classroom.", Email = "a.turing@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS301", Title = "Data Structures & Algorithms", Description = "Advanced study of data organization and algorithm design. Topics include trees, graphs, sorting, searching, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 3, Code = "CS450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and practical applications.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[5], IsFeatured = true },
            new() { Id = 4, Code = "MATH201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, and eigenvalues with applications.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 5, Code = "MATH301", Title = "Abstract Algebra", Description = "Groups, rings, fields, and their properties. Includes homomorphisms, quotient structures, and polynomial rings.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 6, Code = "MATH150", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 7, Code = "ENG110", Title = "Composition & Rhetoric", Description = "Develop effective academic writing skills. Focus on argumentation, research, and clear communication.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 8, Code = "ENG250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and society.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:30 PM", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 9, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 10, Code = "PHYS320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave functions, operators, the Schrödinger equation, and atomic structure.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 11, Code = "HIST101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the modern era, examining political, social, and cultural developments.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 12, Code = "HIST340", Title = "Medieval Europe", Description = "In-depth study of European society, politics, and culture from the fall of Rome to the Renaissance.", Credits = 3, Schedule = "Tue/Thu 10:00–11:30 AM", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[4], IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        return request.CourseId > 0
            && !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId);
    }
}

