@page "/departments/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(department?.Name ?? "Department Not Found")</PageTitle>

@if (department is null)
{
    <h1>Department Not Found</h1>
    <a href="departments" class="btn btn-secondary">Back to Departments</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active">@department.Name</li>
        </ol>
    </nav>

    <h1>@department.Name <span class="badge bg-secondary">@department.Code</span></h1>
    <p class="lead">@department.Description</p>

    <h3 class="mt-4">Courses</h3>
    @if (courses.Any())
    {
        <div class="list-group">
            @foreach (var course in courses)
            {
                <a href="courses/@course.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex w-100 justify-content-between">
                        <h5 class="mb-1">@course.Code — @course.Title</h5>
                        <span class="badge bg-primary">@course.Credits cr</span>
                    </div>
                    <p class="mb-1">@course.Schedule</p>
                    <small class="text-muted">Instructor: @course.Instructor.Name</small>
                </a>
            }
        </div>
    }
    else
    {
        <p class="text-muted">No courses available for this department.</p>
    }
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Department? department;
    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        department = CatalogService.GetDepartment(Id);
        if (department is not null)
            courses = CatalogService.GetCoursesByDepartment(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request below. You will be notified by email once it has been processed.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted Successfully!</h4>
        <p>Your enrollment request for <strong>@selectedCourseName</strong> has been received.</p>
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                    <ValidationMessage For="() => model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title (@course.Department.Name)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (PreselectedCourseId.HasValue && model.CourseId == 0)
            model.CourseId = PreselectedCourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(model.CourseId);
        selectedCourseName = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";

        if (CatalogService.SubmitEnrollmentRequest(model))
        {
            submitted = true;
        }
    }
}

